<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_role(['reseller']); $s=$db->prepare('SELECT id FROM resellers WHERE user_id=? LIMIT 1');$s->execute([$u['id']]);$r=$s->fetch();if(!$r)exit('Reseller profile not found.');$rid=(int)$r['id'];$msg=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$db->prepare('SELECT id,domain FROM licenses WHERE id=? AND reseller_id=?');$s->execute([(int)$_POST['license_id'],$rid]);$l=$s->fetch();if($l&&trim($_POST['new_domain'])){$q=$db->prepare('INSERT INTO reissue_requests(license_id,reseller_id,current_domain,new_domain,reason,status) VALUES(?,?,?,?,?,"pending")');$q->execute([$l['id'],$rid,$l['domain'],trim($_POST['new_domain']),trim($_POST['reason'])?:null]);$msg='Reissue request submitted.';}}
$s=$db->prepare('SELECT id,license_key,domain,status,expires_at FROM licenses WHERE reseller_id=? ORDER BY id DESC');$s->execute([$rid]);$licenses=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkyNoc Reseller</title><style>*{box-sizing:border-box}body{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:#f6f8fb;margin:0;color:#0f172a}.nav{background:#111827;color:#fff;padding:15px 5%;display:flex;justify-content:space-between;align-items:center;gap:15px}.nav a{color:#fff;text-decoration:none}.wrap{max-width:1050px;margin:25px auto;padding:0 16px}.card{background:#fff;padding:20px;border-radius:16px;margin-bottom:18px;border:1px solid #e5e7eb;box-shadow:0 4px 20px #0f172a0a}.table-wrap{overflow-x:auto;border-radius:14px}table{width:100%;min-width:620px;border-collapse:collapse;background:#fff}td,th{padding:13px;border-bottom:1px solid #eef2f7;text-align:left;font-size:14px}input,textarea,select,button{padding:12px;width:100%;box-sizing:border-box;margin:5px 0 9px;border:1px solid #dbe2ea;border-radius:10px;font:inherit}button{background:#111827;color:#fff;border:0;font-weight:700}.msg{background:#ecfdf5;color:#166534;padding:12px;border-radius:10px;margin-bottom:15px}@media(max-width:700px){.nav{align-items:flex-start;flex-direction:column}.wrap{padding:0 12px}.card{padding:16px}h1{font-size:28px}}</head><body><div class="nav"><b>SkyNoc Reseller Portal</b> · <?=e($u['name'])?> · <a style="color:#fff" href="/logout">Logout</a></div><div class="wrap"><h1>My Licenses</h1><?php if($msg):?><div class="msg"><?=e($msg)?></div><?php endif;?><div class="table-wrap"><table><tr><th>License</th><th>Domain</th><th>Status</th><th>Expires</th></tr><?php foreach($licenses as $l):?><tr><td><?=e($l['license_key'])?></td><td><?=e($l['domain'])?></td><td><?=e($l['status'])?></td><td><?=e($l['expires_at'])?></td></tr><?php endforeach;?></table></div><div class="card"><h3>Request Reissue</h3><form method="post"><?=csrf_field()?><select name="license_id" required><?php foreach($licenses as $l):?><option value="<?=$l['id']?>"><?=e($l['license_key'].' — '.$l['domain'])?></option><?php endforeach;?></select><input name="new_domain" placeholder="New domain" required><textarea name="reason" placeholder="Reason"></textarea><button>Submit Reissue Request</button></form></div></div></body></html>